reference_solution:
def least_crossed_bricks(wall):
    from collections import Counter
    edges=Counter()
    for row in wall:
        total=0
        for width in row[:-1]:
            total+=width;edges[total]+=1
    return len(wall)-max(edges.values(),default=0)

